import json
valid = 0
requests = 0
with open('transcripts/run.jsonl') as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except Exception:
            continue
        if not isinstance(obj, dict):
            continue
        valid += 1
        try:
            if obj['payload']['role'] == 'assistant':
                requests += 1
        except (KeyError, TypeError):
            pass
print('valid', valid)
print('requests', requests)
